import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,Entrar,Destello,sacudida,golpe} from './kit';
// VARIADO 2026-11-28 15:00 · ¿Te vibró el bolsillo y no había nada? · 2.5D: volumen (Vol/Vg), 3 capas con parallax, giro leve, sombras en el suelo.
// Herramientas copiadas de docs/referencia_25D_Escena.tsx (Defs, Vol, Brillo2, caps, Bokeh, capas); los dibujos son nuevos.
export const SUBS={arriba:1330,size:84,acento:'#C6FF1A'};
const LIM='#C6FF1A',MG='#FF2E9A',CY='#2EE6FF',GO='#FFC21A';
const A=[0,8,23,29,41,58,66,76,83,92,100,113,126,136,145].map(T);
const S0=A.map((t,i)=>i?t-.15:0); // el corte a la escena nueva entra 0,15 s antes de su primera palabra
const SE=(i:number)=>i===14?DUR:S0[i+1];
const W=(p:string,n=1)=>en(p,n)-.2; // la imagen entra 6 cuadros (0,2 s) antes de la palabra
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const li=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],clamp);
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const rr=(x:number,y:number,w:number,h:number,r:number)=>`M${x+r} ${y}H${x+w-r}A${r} ${r} 0 0 1 ${x+w} ${y+r}V${y+h-r}A${r} ${r} 0 0 1 ${x+w-r} ${y+h}H${x+r}A${r} ${r} 0 0 1 ${x} ${y+h-r}V${y+r}A${r} ${r} 0 0 1 ${x+r} ${y}Z`;
// Cápsula cerrada de (x1,y1) a (x2,y2) con grosor w: dedos, brazos y cuellos con volumen (no trazos sueltos).
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
// Brazo de dos tramos: devuelve codo y muñeca real para llegar a (wx,wy).
const ik=(sx:number,sy:number,wx:number,wy:number,u1:number,u2:number,sg:number)=>{const dx=wx-sx,dy=wy-sy;let d=Math.hypot(dx,dy);d=Math.min(Math.max(d,Math.abs(u1-u2)+1),u1+u2-1);const th=Math.atan2(dy,dx),a=Math.acos((u1*u1+d*d-u2*u2)/(2*u1*d));
 return [sx+u1*Math.cos(th+sg*a),sy+u1*Math.sin(th+sg*a),sx+d*Math.cos(th),sy+d*Math.sin(th)];};
type C3=[string,string,string];type P2=[number,number];type H=(x:number,y:number,a:number)=>React.ReactNode;
const SKN:C3=['#e6b084','#a8693f','#5a2c14'],HAIR:C3=['#4a3a34','#1a100c','#000000'],YEL:C3=['#ffe58a','#FFC21A','#a86a00'],JEAN:C3=['#7a8cf8','#2c3fb0','#0e1858'];
const PNK:C3=['#ffd0dc','#e8809a','#8a3550'],GOLD3:C3=['#fff2b0','#FFC21A','#a86a00'],BLU:C3=['#8ec8ff','#2a6bff','#0a2a8a'];
const useUid=()=>'u'+React.useId().replace(/[^a-zA-Z0-9]/g,'');
// Volumen: color medio, sombra suave abajo-derecha, luz suave arriba-izquierda y borde fino.
const Vol:React.FC<{d:string;c:C3;sw?:number;o?:number;borde?:string}>=({d,c,sw=70,o=24,borde})=>{const id=useUid();return <g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;};
// Volumen barato (degradado luz-sombra) para formas chicas: dedos, brazos, tapas.
const Vg:React.FC<{d:string;c:C3;w?:number;borde?:string}>=({d,c,w=3,borde})=>{const id=useUid();return <g>
 <defs><linearGradient id={id} x1='0' y1='0' x2='1' y2='1'><stop stopColor={c[0]}/><stop offset='.5' stopColor={c[1]}/><stop offset='1' stopColor={c[2]}/></linearGradient></defs>
 <path d={d} fill={`url(#${id})`} stroke={borde||c[2]} strokeWidth={w} strokeOpacity={.6} strokeLinejoin='round'/></g>;};
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
