 <radialGradient id='magG' cx='.35' cy='.3'><stop stopColor='#ffe0f0'/><stop offset='.45' stopColor={MG}/><stop offset='1' stopColor='#8a0a52'/></radialGradient>
 <radialGradient id='oro' cx='.35' cy='.3'><stop stopColor='#fff6b0'/><stop offset='.5' stopColor={GO}/><stop offset='1' stopColor='#a86a00'/></radialGradient>
