 <linearGradient id='ghostG' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ffd0ea' stopOpacity='.8'/><stop offset='1' stopColor={MG} stopOpacity='.18'/></linearGradient>
 <linearGradient id='denim' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#7a8cf8'/><stop offset='.5' stopColor='#3448c0'/><stop offset='1' stopColor='#121c70'/></linearGradient>
