 <pattern id='twill' width='16' height='16' patternUnits='userSpaceOnUse' patternTransform='rotate(40)'><rect width='16' height='7' fill='#fff' opacity='.1'/><rect y='9' width='16' height='3' fill='#000' opacity='.12'/></pattern>
 <pattern id='tile' width='140' height='140' patternUnits='userSpaceOnUse'><rect x='6' y='6' width='128' height='128' rx='14' fill='#fff' opacity='.12'/><rect x='6' y='6' width='128' height='128' rx='14' fill='none' stroke='#055a68' strokeWidth='6' opacity='.7'/><path d='M20 22H84' stroke='#fff' strokeWidth='7' strokeLinecap='round' opacity='.4'/></pattern>
</defs>;
const Bokeh:React.FC<{s:number;i:number;col:string;cerca?:boolean}>=({s,i,col,cerca=false})=><g>{Array.from({length:cerca?6:14}).map((_,j)=>{const r=cerca?60+((j*37+i*11)%70):18+((j*29+i*7)%40);const x=((j*263+i*97)%1300)-110,y=((j*389+i*151)%2100)-90;return <circle key={j} cx={x+Math.sin(s*.6+j)*30} cy={y+Math.cos(s*.5+j)*30} r={r} fill={cerca?'#fff':col} opacity={cerca?.18:.35} filter={cerca?'url(#b18)':'url(#b6)'}/>;})}</g>;
