 return <g key={j} opacity={o}><path d={d} fill='none' stroke={c} strokeWidth={30} opacity={.35} filter='url(#b6)'/><path d={d} fill='none' stroke={c} strokeWidth={14} strokeLinecap='round'/><path d={d} fill='none' stroke='#fff' strokeWidth={4} opacity={.7} strokeLinecap='round'/></g>;})}</g>;
