 return <g transform={`translate(${x} ${y}) scale(${e})`}><rect x={-w/2+6} y={-h/2+12} width={w} height={h} rx={h*.3} fill='#000' opacity={.45} filter='url(#b6)'/><rect x={-w/2} y={-h/2} width={w} height={h} rx={h*.3} fill='#14052f' stroke={c} strokeWidth={6}/><rect x={-w/2+10} y={-h/2+7} width={w-20} height={h*.28} rx={h*.14} fill='#fff' opacity={.14}/>
