 {st==='call'&&<g><circle cy={-60} r={78+Math.sin(s*12)*6} fill='#fff' opacity={.25}/><circle cy={-60} r={62} fill='#fff'/><circle cy={-80} r={20} fill='#e0242a'/><path d='M-34 -30Q0 -70 34 -30Z' fill='#e0242a'/><circle cx={-70} cy={190} r={42} fill='#ff3a3a'/><circle cx={70} cy={190} r={42} fill='#3ddc64'/></g>}
 <path d='M-134 -272H30L-134 -50Z' fill='#fff' opacity={.09}/>
 <rect x={-48} y={-266} width={96} height={24} rx={12} fill='#000'/><circle cx={30} cy={-254} r={5} fill='#243a6a'/>
