const Mano:React.FC<{x:number;y:number;rot?:number;k?:number;f?:number;palma?:boolean}>=({x,y,rot=0,k=1,f=0,palma=false})=><g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
 <Vg d={caps(-42,-26,-90-f*14,-78+f*6,28)} c={SKN}/>
 <Vg d='M-46 6C-58 -34 -54 -78 -42 -104L42 -104C54 -78 58 -34 46 6C26 22 -26 22 -46 6Z' c={SKN}/>
 {[[-33,66],[-11,82],[11,76],[33,58]].map(([bx,len],j)=>{const a=(j-1.5)*f*.2,tx=bx+Math.sin(a)*len,ty=-96-Math.cos(a)*len;return <g key={j}><Vg d={caps(bx,-96,tx,ty,25)} c={SKN}/>{!palma&&<ellipse cx={tx} cy={ty+11} rx={9} ry={7} fill='#f6d2b4' stroke={SKN[2]} strokeWidth={1.5} opacity={.9}/>}</g>;})}
 {!palma&&[0,1,2,3].map(j=><circle key={j} cx={-33+j*22} cy={-88} r={5} fill={SKN[2]} opacity={.35}/>)}
 {palma&&<g stroke={SKN[2]} strokeWidth={4} fill='none' opacity={.5} strokeLinecap='round'><path d='M-30 -30Q0 -10 34 -50'/><path d='M-34 -60Q0 -44 30 -78'/></g>}
</g>;
